begin;
create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select no_plan();
update public.community_operations set enabled=true,enrollment=true,discovery=true,publish=true,engagement=true,cohort_required=false;
update public.community_feature_controls set enabled=true where feature in('groups','challenges');
insert into auth.users(id,email) values('61000000-0000-4000-8000-000000000001','challenge-a@mizyun.test'),('61000000-0000-4000-8000-000000000002','challenge-b@mizyun.test'),('61000000-0000-4000-8000-000000000003','challenge-c@mizyun.test');update public.profiles set birth_year=1990 where id::text like '61000000%';
set local role authenticated;set local request.jwt.claim.role='authenticated';set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000001';select * from public.community_save_profile('challenge_a','A','AA',null,true,true,'2026-09-30');
set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000002';select * from public.community_save_profile('challenge_b','B','BB',null,true,true,'2026-09-30');
set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000003';select * from public.community_save_profile('challenge_c','C','CC',null,true,true,'2026-09-30');
reset role;set local request.jwt.claim.role='service_role';insert into public.community_groups(id,user_id,created_by,operation_id,name,rules) values('62000000-0000-4000-8000-000000000001','61000000-0000-4000-8000-000000000001','61000000-0000-4000-8000-000000000001','63000000-0000-4000-8000-000000000001','Consistency','Be kind');
insert into public.community_group_members(group_id,user_id,role,state,generation,joined_at) select '62000000-0000-4000-8000-000000000001',user_id,case when user_id::text like '%001' then 'owner' else 'member' end,'member',generation,now() from public.community_profiles where user_id in('61000000-0000-4000-8000-000000000001','61000000-0000-4000-8000-000000000002');
insert into public.workouts(id,user_id,name,started_at,completed_at,details) values('65000000-0000-4000-8000-000000000001','61000000-0000-4000-8000-000000000001','Private workout',now(),now(),'{"workoutLifecycle":{"kind":"session"}}');
create temp table challenge_create(args jsonb);insert into challenge_create values(jsonb_build_object('id','64000000-0000-4000-8000-000000000001','groupId','62000000-0000-4000-8000-000000000001','title','Consistency together','startDay',current_date,'endDay',current_date+6,'timezone','UTC','goalDays',4,'confirmed',true));grant select on challenge_create to authenticated;
create temporary table challenge_safety_state(challenge uuid primary key,receipt uuid,report uuid);
grant all on challenge_safety_state to authenticated;
set local role authenticated;set local request.jwt.claim.role='authenticated';set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000001';
select is((select result->'challenge'->>'myProgress' from public.community_challenges_rpc('create',(select args from challenge_create))),null::text,'Creation does not auto-join or ingest private workouts');
select is((select result->'challenge'->>'participants' from public.community_challenges_rpc('get','{"id":"64000000-0000-4000-8000-000000000001"}')),'0','Participants require independent explicit consent');
select lives_ok($$select * from public.community_challenges_rpc('create',(select args from challenge_create))$$,'Lost-create retry does not duplicate');
select throws_ok($$select * from public.community_challenges_rpc('create',(select args||'{"title":"Changed"}' from challenge_create))$$,'P0001','community_conflict','Conflicting create cannot overwrite goal');
select throws_ok($$select * from public.community_challenges_rpc('join','{"id":"64000000-0000-4000-8000-000000000001"}')$$,'P0001','community_invalid_input','Raw join requires actual confirmation');
select * from public.community_challenges_rpc('join','{"id":"64000000-0000-4000-8000-000000000001","confirmed":true}');
select is((select result->'challenge'->>'myProgress' from public.community_challenges_rpc('contribute',jsonb_build_object('id','64000000-0000-4000-8000-000000000001','day',current_date,'kind','workout','sourceWorkoutId','65000000-0000-4000-8000-000000000001','confirmed',true))),'1','Opted-in owned workout declaration counts once');
select is((select result->'challenge'->>'myProgress' from public.community_challenges_rpc('contribute',jsonb_build_object('id','64000000-0000-4000-8000-000000000001','day',current_date,'kind','workout','sourceWorkoutId','65000000-0000-4000-8000-000000000001','confirmed',true))),'1','Repeated declaration cannot inflate progress');
select is((select count(*) from public.community_export_page('challengeContributions')),1::bigint,'Own export has only deliberate declarations');
set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000002';select * from public.community_challenges_rpc('join','{"id":"64000000-0000-4000-8000-000000000001","confirmed":true}');
insert into challenge_safety_state(challenge,receipt) select '64000000-0000-4000-8000-000000000001',id from public.community_report_receipts_for_caller() where target_type='challenge' and target_id='64000000-0000-4000-8000-000000000001';
select is((select count(*) from challenge_safety_state),1::bigint,'Delivered challenge DTO automatically records exact reporting authority');
select is((select id from public.community_issue_report_receipt('challenge','64000000-0000-4000-8000-000000000001')),(select receipt from challenge_safety_state),'Repeated receipt issuance returns original delivery receipt');
select lives_ok($$select * from public.community_challenges_rpc('list','{"groupId":"62000000-0000-4000-8000-000000000001"}')$$,'Authorized challenge list preserves safety receipts');
select is((select count(*) from public.community_report_receipts_for_caller() where target_type='challenge'),1::bigint,'Repeated list/get delivery does not multiply receipts');
select throws_ok($$select * from public.community_challenges_rpc('contribute',jsonb_build_object('id','64000000-0000-4000-8000-000000000001','day',current_date,'kind','workout','sourceWorkoutId','65000000-0000-4000-8000-000000000001','confirmed',true))$$,'P0001','community_unavailable','Forged another user diary provenance denied');
select is((select result->'challenge'->>'myProgress' from public.community_challenges_rpc('contribute',jsonb_build_object('id','64000000-0000-4000-8000-000000000001','day',current_date,'kind','rest','confirmed',true))),'1','Accessible rest alternative receives equal credit');
set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000001';
select * from public.community_challenges_rpc('create',(select args||'{"id":"64000000-0000-4000-8000-000000000002","title":"Second consistency goal"}' from challenge_create));
set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000002';
select * from public.community_challenges_rpc('list','{"groupId":"62000000-0000-4000-8000-000000000001"}');
insert into challenge_safety_state(challenge,receipt) select '64000000-0000-4000-8000-000000000002',id from public.community_report_receipts_for_caller() where target_type='challenge' and target_id='64000000-0000-4000-8000-000000000002';
reset role;
delete from public.community_challenges where id='64000000-0000-4000-8000-000000000002';
set local role authenticated;
update challenge_safety_state set report=(select id from public.community_submit_report('challenge',challenge::text,'spam','Goal seen before deletion',receipt)) where challenge='64000000-0000-4000-8000-000000000002';
select ok((select report is not null from challenge_safety_state where challenge='64000000-0000-4000-8000-000000000002'),'View then physical challenge deletion retains exact reporting authority');
select is((select id from public.community_submit_report('challenge','64000000-0000-4000-8000-000000000002','spam','More context',(select receipt from challenge_safety_state where challenge='64000000-0000-4000-8000-000000000002'))),(select report from challenge_safety_state where challenge='64000000-0000-4000-8000-000000000002'),'Deleted challenge repeated reports return one existing case');
set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000003';select throws_ok($$select * from public.community_challenges_rpc('get','{"id":"64000000-0000-4000-8000-000000000001"}')$$,'P0001','community_unavailable','Group UUID does not allow stranger progress access');
select throws_ok($$select * from public.community_challenge_contributions$$,'42501',null,'Raw database cannot expose private provenance');
reset role;update public.workouts set completed_at=null where id='65000000-0000-4000-8000-000000000001';set local role authenticated;set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000001';
select is((select result->'challenge'->>'myProgress' from public.community_challenges_rpc('get','{"id":"64000000-0000-4000-8000-000000000001"}')),'0','Reopening source workout invalidates declaration');
reset role;delete from public.workouts where id='65000000-0000-4000-8000-000000000001';set local role authenticated;
select is((select result->'challenge'->>'myProgress' from public.community_challenges_rpc('get','{"id":"64000000-0000-4000-8000-000000000001"}')),null::text,'Deleting source removes independent declaration without counting zero effort');
set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000002';
insert into public.community_blocks(blocker_user_id,blocked_user_id) values(auth.uid(),'61000000-0000-4000-8000-000000000001');
select throws_ok($$select * from public.community_challenges_rpc('get','{"id":"64000000-0000-4000-8000-000000000001"}')$$,'P0001','community_unavailable','Bilateral block immediately revokes challenge display');
update challenge_safety_state set report=(select id from public.community_submit_report('challenge',challenge::text,'harassment',null,receipt)) where challenge='64000000-0000-4000-8000-000000000001';
select ok((select report is not null from challenge_safety_state where challenge='64000000-0000-4000-8000-000000000001'),'View then bilateral block retains exact challenge reporting authority');
select is((select id from public.community_submit_report('challenge','64000000-0000-4000-8000-000000000001','harassment',null,(select receipt from challenge_safety_state where challenge='64000000-0000-4000-8000-000000000001'))),(select report from challenge_safety_state where challenge='64000000-0000-4000-8000-000000000001'),'Blocked challenge report retries reuse one case');
select throws_ok($$select * from public.community_submit_report('challenge','64000000-0000-4000-8000-000000000001','harassment',null,'64000000-0000-4000-8000-000000000099')$$,'P0001','community_unavailable','Forged explicit challenge receipt cannot reuse a case');
set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000003';
select throws_ok($$select * from public.community_submit_report('challenge','64000000-0000-4000-8000-000000000001','harassment',null,(select receipt from challenge_safety_state where challenge='64000000-0000-4000-8000-000000000001'))$$,'P0001','community_unavailable','Stranger cannot use another viewer challenge receipt');
reset role;
select is((select count(*) from public.community_reports where reporter_user_id='61000000-0000-4000-8000-000000000002' and target_type='challenge'),2::bigint,'Two delivered challenge targets create exactly two cases');
select is((select report_count from public.community_report_usage where user_id='61000000-0000-4000-8000-000000000002' and report_date=(now() at time zone 'UTC')::date),2,'Repeated challenge reports consume one quota unit per case');
select ok((select evidence_snapshot->>'title'='Second consistency goal' and not evidence_snapshot ? 'sourceWorkoutId' from public.community_reports where target_type='challenge' and target_id='64000000-0000-4000-8000-000000000002'),'Deleted challenge evidence includes exact public goal without private provenance');
update public.community_report_receipts set expires_at=now()-interval '1 second' where id=(select receipt from challenge_safety_state where challenge='64000000-0000-4000-8000-000000000002');
set local role authenticated;set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000002';
select throws_ok($$select * from public.community_submit_report('challenge','64000000-0000-4000-8000-000000000002','spam',null,(select receipt from challenge_safety_state where challenge='64000000-0000-4000-8000-000000000002'))$$,'P0001','community_unavailable','Expired challenge receipt cannot reuse an existing case');
reset role;
delete from public.community_blocks where blocker_user_id='61000000-0000-4000-8000-000000000002';
reset role;update public.community_group_members set state='removed' where user_id='61000000-0000-4000-8000-000000000002';set local role authenticated;set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000002';
select throws_ok($$select * from public.community_challenges_rpc('get','{"id":"64000000-0000-4000-8000-000000000001"}')$$,'P0001','community_unavailable','Removed member cannot view historical challenge');
reset role;update public.community_feature_controls set enabled=false where feature='challenges';set local role authenticated;
select lives_ok($$select * from public.community_challenges_rpc('leave','{"id":"64000000-0000-4000-8000-000000000001"}')$$,'Leave removes contributions even with engagement switched off');
select is((select count(*) from public.community_export_page('challengeContributions')),0::bigint,'Leaving removes own exported contributions');
reset role;
update public.community_feature_controls set enabled=true where feature='challenges';
update public.community_group_members set state='member',joined_at=now()+interval '1 second' where user_id='61000000-0000-4000-8000-000000000002';
set local role authenticated;set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000002';
select throws_ok($$select * from public.community_challenges_rpc('get','{"id":"64000000-0000-4000-8000-000000000001"}')$$,'P0001','community_unavailable','Fresh later group incarnation cannot regain earlier challenge history');
select * from finish();rollback;
